use vstd::prelude::*;

verus! {
    // Prefix a 0.0 to the input vector c, returning a new vector.
    // Ensures the result has length one more than c,
    // the first element is exactly 0.0, and
    // for every i < c.len(), result[i+1] == c[i].
    fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result@.len() == c@.len() + 1,
            result@[0] == 0.0_f32,
            forall |k: usize| k < c@.len() ==> result@[k+1] == c@[k],
    {
        // Start with an empty vector and push the 0.0 prefix
        let mut result: Vec<f32> = Vec::new();
        result.push(0.0_f32);

        // i counts how many elements of c we have copied so far
        let mut i: usize = 0;
        while i < c.len()
            invariant
                // 0 <= i <= c.len()
                i <= c.len(),
                // result.len() == 1 (the prefix) + i
                result.len() == i + 1,
                // The first element is always 0.0
                result@[0] == 0.0_f32,
                // For each k < i, we've already copied c[k] to result[k+1]
                forall |k: usize| k < i ==> result@[k+1] == c@[k],
            decreases
                // We will eventually finish copying all elements
                c.len() - i,
        {
            // Copy the next element
            result.push(c[i]);
            i = i + 1;
        }

        result
    }
}

